import { createRouter, createWebHashHistory } from 'vue-router';
import ScheduleImport from '../views/ScheduleImport.vue';
import WorkstationReport from '../views/WorkstationReport.vue';

const routes = [
  {
    path: '/',
    name: 'ScheduleImport',
    component: ScheduleImport
  },
  {
    path: '/workstation',
    name: 'WorkstationReport',
    component: WorkstationReport
  }
];

const router = createRouter({
  history: createWebHashHistory(),
  routes
});

export default router;