<template>
  <div>
    <!-- 頁面切換功能列 -->
    <nav class="navbar">
      <router-link to="/" exact-active-class="active">生管匯入排程</router-link>
      <router-link to="/workstation" exact-active-class="active">工站回報</router-link>
    </nav>
    <h1>生管匯入排程</h1>
    <button @click="syncOrders" :disabled="loading">
      <span v-if="loading">同步中...</span>
      <span v-else>即時同步SAP訂單</span>
    </button>
    <div v-if="loading" class="loader"></div>
    <OrderList v-if="orders.length && !loading" :orders="orders" />
  </div>
</template>

<script>
import OrderList from '../components/OrderList.vue';
import { syncOrders } from '../services/sapSyncService.js';
import { mapGetters, mapActions } from 'vuex';

export default {
  components: { OrderList },
  computed: {
    ...mapGetters(['orders'])
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    ...mapActions(['updateOrders']),
    async syncOrders() {
      this.loading = true;
      try {
        const orders = await syncOrders();
        this.updateOrders(orders); // 寫入store
      } catch (error) {
        console.error('同步訂單失敗:', error);
      } finally {
        this.loading = false;
      }
    }
  }
};
</script>

