<template>
  <div>
    <!-- 頁面切換功能列 -->
    <nav class="navbar">
      <router-link to="/" exact-active-class="active">生管匯入排程</router-link>
      <router-link to="/workstation" exact-active-class="active">工站回報</router-link>
    </nav>
    <h1>工站回報</h1>
    <form @submit.prevent="submitReport">
      <div class="row">
        <div class="field">
          <label>生產單號：</label>
          <select v-model="form.生產單號" required>
            <option value="" disabled>請選擇</option>
            <option v-for="order in uniqueOrderNos" :key="order" :value="order">{{ order }}</option>
          </select>
        </div>
        <div class="field">
          <label>批號：</label>
          <select v-model="form.批號" required>
            <option value="" disabled>請選擇</option>
            <option v-for="batch in batchOptions" :key="batch" :value="batch">{{ batch }}</option>
          </select>
        </div>
        <div class="field">
          <label>工作站：</label>
          <select v-model="form.工作站" required>
            <option value="" disabled>請選擇</option>
            <option v-for="ws in workstationOptions" :key="ws" :value="ws">{{ ws }}</option>
          </select>
        </div>
      </div>
      <div class="row">
        <div class="field">
          <label>裝機開始時間：</label>
          <input type="datetime-local" v-model="form.裝機開始時間" required>
        </div>
        <div class="field">
          <label>裝機完成時間：</label>
          <input type="datetime-local" v-model="form.裝機完成時間" required>
        </div>
      </div>
      <div class="row">
        <div class="field">
          <label>作業開始時間：</label>
          <input type="datetime-local" v-model="form.作業開始時間" required>
        </div>
        <div class="field">
          <label>作業完成時間：</label>
          <input type="datetime-local" v-model="form.作業完成時間" required>
        </div>
      </div>
      <div class="row">
        <div class="field">
          <label>工單數量：</label>
          <input type="number" :value="orderQuantity" readonly>
        </div>
        <div class="field">
          <label>排驗數量：</label>
          <input type="number" v-model.number="form.排驗數量" min="0">
        </div>
        <div class="field">
          <label>完成數量：</label>
          <input type="number" v-model.number="form.完成數量" :min="0">
        </div>
      </div>
      <div class="text-left">
        <label>不良原因列表：</label><button type="button" @click="addDefect">新增不良原因</button>
        <div v-for="(item, idx) in form.defects" :key="idx" class="defect-row">
          <div class="row">
            <div class="field" style="flex: 1;">
              <label>不良原因：</label>
              <select v-model="item.reason" required>
                <option value="" disabled>請選擇</option>
                <option v-for="reason in defectReasons" :key="reason" :value="reason">{{ reason }}</option>
              </select>
            </div>
            <div class="field" style="flex: 1;">
              <label>數量：</label>
              <input type="number" v-model.number="item.qty" min="1" placeholder="數量" required style="width:80px;">
            </div>
            <div class="field" style="flex: 1;">
              <button type="button" @click="removeDefect(idx)" v-if="form.defects.length > 1">移除</button>
            </div>
          </div>
        </div>
      </div>
      <div>
        <label>備註說明：</label>
        <textarea v-model="form.備註說明" required></textarea>
      </div>
      <button type="submit">送出回報</button>
    </form>
    <div v-if="submitted" class="success">回報已送出！</div>
  </div>
</template>

<script>
import { mapGetters } from 'vuex';

export default {
  name: 'WorkstationReport',
  data() {
    return {
      form: {
        生產單號: '',
        批號: '',
        工作站: '',
        裝機開始時間: '',
        裝機完成時間: '',
        作業開始時間: '',
        作業完成時間: '',
        完成數量: 0,
        排驗數量: 0,
        備註說明: '',
        defects: [{ reason: '', qty: 0 }]
      },
      submitted: false,
      defectReasons: ['不良原因1', '不良原因2', '不良原因3'] // 示例不良原因
    };
  },
  computed: {
    ...mapGetters(['orders']),
    uniqueOrderNos() {
      return [...new Set(this.orders.map(o => o.生產單號))];
    },
    batchOptions() {
      if (!this.form.生產單號) return [];
      return [
        ...new Set(
          this.orders
            .filter(o => o.生產單號 === this.form.生產單號)
            .map(o => o.批號)
        )
      ];
    },
    workstationOptions() {
      if (!this.form.生產單號 || !this.form.批號) return [];
      return [
        ...new Set(
          this.orders
            .filter(
              o =>
                o.生產單號 === this.form.生產單號 &&
                o.批號 === this.form.批號
            )
            .map(o => o.工作站)
        )
      ];
    },
    orderQuantity() {
      // 根據選擇的生產單號、批號、工作站取得工單數量
      const found = this.orders.find(
        o =>
          o.生產單號 === this.form.生產單號 &&
          o.批號 === this.form.批號 &&
          o.工作站 === this.form.工作站
      );
      // 預設完成數量等於工單數量
      if (found && this.form.完成數量 === 0) {
        this.form.完成數量 = found.數量;
      }
      return found ? found.數量 : '';
    }
  },
  watch: {
    'form.生產單號'() {
      this.form.批號 = '';
      this.form.工作站 = '';
      this.form.完成數量 = 0;
      this.form.排驗數量 = 0;
    },
    'form.批號'() {
      this.form.工作站 = '';
      this.form.完成數量 = 0;
      this.form.排驗數量 = 0;
    },
    'form.工作站'() {
      this.form.完成數量 = 0;
      this.form.排驗數量 = 0;
    }
  },
  methods: {
    submitReport() {
      this.submitted = true;
      setTimeout(() => {
        this.submitted = false;
        this.form = {
          生產單號: '',
          批號: '',
          工作站: '',
          裝機開始時間: '',
          裝機完成時間: '',
          作業開始時間: '',
          作業完成時間: '',
          完成數量: 0,
          排驗數量: 0,
          備註說明: '',
          defects: [{ reason: '', qty: 0 }]
        };
      }, 2000);
    },
    addDefect() {
      this.form.defects.push({ reason: '', qty: 0 });
    },
    removeDefect(idx) {
      this.form.defects.splice(idx, 1);
    }
  }
};
</script>

<style scoped>
.navbar {
  display: flex;
  gap: 20px;
  margin-bottom: 24px;
  background: #f5f5f5;
  padding: 12px 20px;
  border-radius: 8px;
}
.navbar a {
  text-decoration: none;
  color: #333;
  font-weight: bold;
  padding: 6px 16px;
  border-radius: 4px;
  transition: background 0.2s;
}
.navbar a.active, .navbar a:hover {
  background: #3498db;
  color: #fff;
}
form {
  margin-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-width: 600px;
}
.row {
  display: flex;
  gap: 16px;
  align-items: flex-end;
}
.field {
  display: flex;
  flex-direction: column;
  flex: 1;
}
label {
  font-weight: bold;
  margin-bottom: 4px;
}
select, textarea, input[type="datetime-local"], input[type="number"] {
  width: 100%;
  padding: 6px;
  border-radius: 4px;
  border: 1px solid #ccc;
}
button[type="submit"] {
  width: 120px;
  padding: 8px;
  background: #3498db;
  color: #fff;
  border: none;
  border-radius: 4px;
  font-weight: bold;
  cursor: pointer;
}
.success {
  margin-top: 16px;
  color: #27ae60;
  font-weight: bold;
}
</style>