import { createStore } from 'vuex';

export default createStore({
  state: {
    orders: []
  },
  mutations: {
    setOrders(state, orders) {
      state.orders = orders;
    }
  },
  actions: {
    updateOrders({ commit }, orders) {
      commit('setOrders', orders);
    }
  },
  getters: {
    orders: state => state.orders
  }
});